private TreeNode<T> rotateRight(TreeNode<T> node){
    TreeNode<T> left = node.left;
    if (left == null) return node; // nothing to rotate
    // detach left subtree's right child and attach to node
    node.left = left.right;
    if (left.right != null) left.right.parent = node;
    // make node the right child of left
    left.right = node;
    // update parent links
    left.parent = node.parent;
    node.parent = left;
    // update the old parent to point to new root
    if (left.parent != null) {
        if (left.parent.left == node) left.parent.left = left;
        else if (left.parent.right == node) left.parent.right = left;
    }
    return left;
