public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    Set<String> visited = new HashSet<>();
    while (true) {
        int start = value.indexOf("${");
        if (start == -1) {
            break;
        }
        int end = value.indexOf('}', start + 2);
        if (end == -1) {
            break;
        }
        String varName = value.substring(start + 2, end);
        if (!visited.add(varName)) {
            // circular reference detected, stop processing
            break;
        }
        String replacement = props.getProperty(varName);
        if (replacement == null) {
            replacement = "";
        }
        value = value.substring(0, start) + replacement + value.substring(end + 1);
    }
    return value;
}<|return|>

