public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return new ArrayList<>();
    }
    // Ignore leading '/' for absolute paths
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    if (path.isEmpty()) {
        return new ArrayList<>();
    }
    String[] segments = path.split("/", -1);
    List<PathSegmentImpl> result = new ArrayList<>();
    for (String seg : segments) {
        String value = seg;
        if (decode) {
            try {
                value = java.net.URLDecoder.decode(seg, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (Exception e) {
                // If decoding fails, keep the original segment
            }
        }
        result.add(new PathSegmentImpl(value, null));
    }
    return result;
