public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c != '\\') {
            sb.append(c);
            continue;
        }
        // c is backslash
        if (i + 1 >= len) {
            // trailing backslash, treat as literal
            sb.append('\\');
            break;
        }
        char next = str.charAt(i + 1);
        // Handle double backslash
        if (next == '\\') {
            sb.append('\\');
            i++; // skip the second backslash
            continue;
        }
        switch (next) {
            case 'b':
                sb.append('\b');
                i++;
                break;
            case 't':
                sb.append('\t');
                i++;
                break;
            case 'n':
                sb.append('\n');
                i++;
                break;
            case 'f':
                sb.append('\f');
                i++;
                break;
            case 'r':
                sb.append('\r');
                i++;
                break;
            case '\"':
                sb.append('\"');
                i++;
                break;
            case '\'':
                sb.append('\'');
                i++;
                break;
            case 'u':
                // Unicode escape \uXXXX
                if (i + 5 >= len) {
                    throw new IllegalArgumentException("Invalid unicode escape at position " + i);
                }
                String hex = str.substring(i + 2, i + 6);
                try {
                    int code = Integer.parseInt(hex, 16);
                    sb.append((char) code);
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("Invalid unicode escape at position " + i, e);
                }
                i += 5; // skip \uXXXX
                break;
            default:
                // Octal escape or unknown
                if (next >= '0' && next <= '7') {
                    int j = i + 1;
                    int end = j;
                    while (end < len && end - j < 3 && str.charAt(end) >= '0' && str.charAt(end) <= '7') {
                        end++;
                    }
                    String oct = str.substring(j, end);
                    try {
                        int val = Integer.parseInt(oct, 8);
                        sb.append((char) val);
                    } catch (NumberFormatException e) {
                        throw new IllegalArgumentException("Invalid octal escape at position " + i, e);
                    }
                    i = end - 1; // will be incremented by loop
                } else {
                    // Unknown escape, keep as is
                    sb.append(next);
                    i++;
                }
                break;
        }
    }
    return sb.toString();
}<|return|>

