private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Create a circulator starting at the given node and direction
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    // If the start node is the stop node, or already satisfies the predicate, return immediately
    if (start.equals(stop) || predicate.test(circ.getNode())) {
        return circ;
    }

    // Traverse the outer face until we hit the stop node or find a node that satisfies the predicate
    while (true) {
        circ.next(); // move to the next node in the specified direction
        Node current = circ.getNode();

        // Stop if we reached the stop node
        if (current.equals(stop)) {
            return circ;
        }

        // Return if the current node satisfies the predicate
        if (predicate.test(current)) {
            return circ;
        }

        // Safety check: if we loop back to the start without finding a match, break to avoid infinite loop
        if (current.equals(start)) {
            return circ;
        }
    }
