int addConstantNameAndType(final String name, final String descriptor){
    // Ensure the UTF-8 entries for name and descriptor exist
    int nameIndex = addConstantUtf8(name);
    int descriptorIndex = addConstantUtf8(descriptor);

    // Search for an existing NameAndType entry with the same indices
    for (int i = 1; i < constantPool.size(); i++) {
        ConstantPoolInfo info = constantPool.get(i);
        if (info instanceof ConstantNameAndTypeInfo) {
            ConstantNameAndTypeInfo nt = (ConstantNameAndTypeInfo) info;
            if (nt.nameIndex == nameIndex && nt.descriptorIndex == descriptorIndex) {
                return i; // Found existing entry
            }
        }
    }

    // Create and add a new NameAndType entry
    ConstantNameAndTypeInfo newEntry = new ConstantNameAndTypeInfo(nameIndex, descriptorIndex);
    constantPool.add(newEntry);
    return constantPool.size() - 1; // Return the index of the new entry
