private String unescapeId(String input){
    if (input == null) return null;
    int len = input.length();
    // Remove surrounding double quotes if present
    if (len >= 2 && input.charAt(0) == '"' && input.charAt(len - 1) == '"') {
        input = input.substring(1, len - 1);
        len = input.length();
    }
    StringBuilder sb = new StringBuilder(len);
    for (int i = 0; i < len; i++) {
        char c = input.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = input.charAt(i + 1);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case '"':
                    sb.append('\"');
                    i++;
                    break;
                case '\'':
                    sb.append('\'');
                    i++;
                    break;
                case '\\':
                    sb.append('\\');
                    i++;
                    break;
                case 'x':
                    if (i + 3 < len) {
                        String hex = input.substring(i + 2, i + 4);
                        try {
                            int val = Integer.parseInt(hex, 16);
                            sb.append((char) val);
                            i += 3;
                        } catch (NumberFormatException e) {
                            sb.append('x');
                            i++;
                        }
                    } else {
                        sb.append('x');
                        i++;
                    }
                    break;
                case 'u':
                    if (i + 5 < len) {
                        String hex = input.substring(i + 2, i + 6);
                        try {
                            int val = Integer.parseInt(hex, 16);
                            sb.append((char) val);
                            i += 5;
                        } catch (NumberFormatException e) {
                            sb.append('u');
                            i++;
                        }
                    } else {
                        sb.append('u');
                        i++;
                    }
                    break;
                case 'U':
                    if (i + 9 < len) {
                        String hex = input.substring(i + 2, i + 10);
                        try {
                            int val = (int) Long.parseLong(hex, 16);
                            sb.append(Character.toChars(val));
                            i += 9;
                        } catch (NumberFormatException e) {
                            sb.append('U');
                            i++;
                        }
                    } else {
                        sb.append('U');
                        i++;
                    }
                    break;
                default:
                    sb.append(next);
                    i++;
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
