    ListNodeImpl<E> next = node.next;

    if (prev == null) {
        // node is the head
        head = next;
    } else {
        prev.next = next;
    }

    if (next == null) {
        // node is the tail
        tail = prev;
    } else {
        next.prev = prev;
    }

    // Clean up the removed node's references
    node.prev = null;
    node.next = null;

