private String parseToken(final char[] terminators) {
    // Assume the class has a String field `input` and an int field `pos` tracking the current position.
    if (input == null || pos >= input.length()) {
        return "";
    }

    StringBuilder sb = new StringBuilder();
    while (pos < input.length()) {
        char c = input.charAt(pos);

        // Check if the current character is one of the terminators.
        boolean isTerminator = false;
        if (terminators != null && terminators.length > 0) {
            for (char t : terminators) {
                if (c == t) {
                    isTerminator = true;
                    break;
                }
            }
        }

        if (isTerminator) {
            // Consume the terminator and stop parsing the token.
            pos++;
            break;
        }

        sb.append(c);
        pos++;
    }

    return sb.toString();
