private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list == this) {
        return;
    }
    // Acquire locks on both lists in a consistent order to avoid deadlock
    Object firstLock;
    Object secondLock;
    if (System.identityHashCode(this) < System.identityHashCode(list)) {
        firstLock = this;
        secondLock = list;
    } else {
        firstLock = list;
        secondLock = this;
    }
    synchronized (firstLock) {
        synchronized (secondLock) {
            ListNodeImpl<E> node = list.head;
            while (node != null) {
                ListNodeImpl<E> next = node.next; // keep reference before removal
                list.removeListNode(node);
                this.addListNode(node);
                node = next;
            }
        }
    }
