private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    for (K key : keys) {
        Integer maxLower = null;
        for (K other : keys) {
            if (other == key) continue;
            if (other instanceof Comparable) {
                @SuppressWarnings("unchecked")
                Comparable<K> comp = (Comparable<K>) other;
                if (comp.compareTo(key) < 0) {
                    Integer val = null;
                    if (other instanceof Number) {
                        val = ((Number) other).intValue();
                    } else {
                        // Fallback if the key cannot be represented as an integer
                        val = Integer.MIN_VALUE;
                    }
                    if (maxLower == null || (val != null && val > maxLower)) {
                        maxLower = val;
                    }
                }
            }
        }
        lowerBounds.add(maxLower != null ? maxLower : Integer.MIN_VALUE);
    }
    return lowerBounds;
}<|return|>

