static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return null;
    }
    int nonNullCount = 0;
    for (Object o : array) {
        if (o != null) {
            nonNullCount++;
        }
    }
    if (nonNullCount == array.length) {
        return (String[]) array;
    }
    String[] result = new String[nonNullCount];
    int idx = 0;
    for (Object o : array) {
        if (o != null) {
            result[idx++] = (String) o;
        }
    }
    return result;
